const siteList = () => (S.sites || '').split(/[,\s]+/).map((u) => u.trim()).filter(Boolean).map((u) => (/^https?:\/\//.test(u) ? u : 'https://' + u));
async function reach(url) {
  const t0 = performance.now(); const ctl = new AbortController(); const to = setTimeout(() => ctl.abort(), 10000);
  try { await fetch(url, { mode: 'no-cors', cache: 'no-store', signal: ctl.signal }); clearTimeout(to); return { up: true, ms: Math.round(performance.now() - t0) }; } catch { clearTimeout(to); return { up: false, ms: 0 }; }
}
async function psi(url) {
  const cats = ['performance', 'seo', 'accessibility', 'best-practices'].map((c) => '&category=' + c).join('');
  const j = await fetchJSON(`https://www.googleapis.com/pagespeedonline/v5/runPagespeed?url=${encodeURIComponent(url)}&strategy=mobile&locale=el${cats}${S.psiKey ? '&key=' + encodeURIComponent(S.psiKey) : ''}`, null, 1);
  const lr = j?.lighthouseResult; if (!lr) return null;
  const sc = {}; Object.values(lr.categories).forEach((c) => (sc[c.id] = Math.round(c.score * 100)));
  const issues = Object.values(lr.audits).filter((a) => a.score !== null && a.score < 0.9 && (a.details?.type === 'opportunity' || ['seo', 'accessibility'].some((k) => lr.categories[k]?.auditRefs?.some((r) => r.id === a.id && r.weight > 0)))).sort((a, b) => (a.score ?? 1) - (b.score ?? 1)).slice(0, 4).map((a) => a.title);
  return { sc, issues, lcp: lr.audits['largest-contentful-paint']?.displayValue };
}
