function nextDate(d, m) { const now = new Date(); now.setHours(0, 0, 0, 0); let x = new Date(now.getFullYear(), m - 1, d); if (x < now) x = new Date(now.getFullYear() + 1, m - 1, d); return x; }
function parseTrip(raw, n) {
  n = wordsToNums(n); const T = n.split(' '); let ci = null, co = null;
  let m = n.match(/(\d{1,2})\s*(?:εωσ|μεχρι|με|-|ωσ|και)\s*(\d{1,2})\s+([α-ω]+)/);
  if (m && monthOfToken(m[3]) >= 0) { const mo = monthOfToken(m[3]) + 1; ci = nextDate(+m[1], mo); co = new Date(ci.getFullYear(), mo - 1, +m[2]); }
  if (!ci) { m = n.match(/(\d{1,2})\s+([α-ω]+)\s*(?:εωσ|μεχρι|με|-|ωσ)\s*(\d{1,2})\s+([α-ω]+)/); if (m && monthOfToken(m[2]) >= 0 && monthOfToken(m[4]) >= 0) { ci = nextDate(+m[1], monthOfToken(m[2]) + 1); co = new Date(ci.getFullYear() + (monthOfToken(m[4]) < monthOfToken(m[2]) ? 1 : 0), monthOfToken(m[4]), +m[3]); } }
  if (!ci) { m = n.match(/(\d{1,2})\s*\/\s*(\d{1,2})/); if (m) ci = nextDate(+m[1], +m[2]); }
  if (!ci) { m = n.match(/(\d{1,2})\s+([α-ω]+)/); if (m && monthOfToken(m[2]) >= 0) ci = nextDate(+m[1], monthOfToken(m[2]) + 1); }
  if (!ci) { const mi = T.map(monthOfToken).find((x) => x >= 0); if (mi != null && mi >= 0) ci = nextDate(1, mi + 1); }
  if (/(αυριο)/.test(n)) ci = addDays(new Date(), 1); if (/(σημερα|απποψε|αποψε)/.test(n)) ci = new Date();
  const nights = n.match(/(\d+)\s*(βραδια|νυχτεσ|νυχτα|βραδυ|μερεσ|διανυκτερευσ)/);
  if (ci && !co) co = addDays(ci, nights ? +nights[1] : 3);
  const ad = n.match(/(\d+)\s*(ατομα|ατομο|ενηλικ|ανθρωπουσ)/); const adults = ad ? +ad[1] : /(μονοσ|μονη|για εμενα)/.test(n) ? 1 : (S.travelAdults || 2);
  const dm = n.match(/(?:\sστη|\sστην|\sστο|\sστον|\sστα|\sστισ|\sσε|\sγια)\s+(?!\d)([α-ωa-z][α-ωa-z\s-]*?)(?=\s+(?:απο|για|με|στισ|τον|την|το|\d)|$)/);
  let dest = dm ? rawSpan(raw, n, dm[1].trim()) : '';
  dest = dest.replace(/^(το|τη|την|τον)\s+/i, '').replace(/\s*(φθηνο|φθηνα|οικονομικο|ξενοδοχειο|ξενοδοχεία)$/i, '').trim();
  return { dest, ci, co, adults, cheap: /(φθην|οικονομικ|χαμηλη τιμη)/.test(n) };
}
