  items.forEach((x) => addShop(x, `Βαλίτσα: ${t.dest}`)); renderMem();
  return `Έφτιαξα λίστα για τη βαλίτσα με ${items.length} πράγματα${mx != null ? `, για θερμοκρασίες έως ${Math.round(mx)} βαθμούς${rain ? ' με πιθανότητα βροχής' : ''}` : ''}. Θα τη βρείτε στα Ψώνια, ως «Βαλίτσα: ${t.dest}».`;
