function moonSign(d = new Date()) { const D = jd(d) - 2451545.0; const L = 218.316 + 13.176396 * D, M = 134.963 + 13.064993 * D; let lon = (L + 6.289 * Math.sin((M * Math.PI) / 180)) % 360; if (lon < 0) lon += 360; return ['Κριό', 'Ταύρο', 'Διδύμους', 'Καρκίνο', 'Λέοντα', 'Παρθένο', 'Ζυγό', 'Σκορπιό', 'Τοξότη', 'Αιγόκερω', 'Υδροχόο', 'Ιχθείς'][Math.floor(lon / 30)]; }
