const SIGN_THEMES = { 'Κριό': 'νέα ξεκινήματα, θάρρος και δράση', 'Ταύρο': 'σταθερότητα, οικονομικά και απολαύσεις του σώματος', 'Διδύμους': 'επικοινωνία, μάθηση και περιέργεια', 'Καρκίνο': 'σπίτι, οικογένεια και συναίσθημα', 'Λέοντα': 'δημιουργικότητα, αυτοπεποίθηση και χαρά', 'Παρθένο': 'υγεία, οργάνωση και καθημερινές συνήθειες', 'Ζυγό': 'σχέσεις, ισορροπία και ομορφιά', 'Σκορπιό': 'μεταμόρφωση, βάθος και απελευθέρωση', 'Τοξότη': 'ταξίδια, σοφία και αισιοδοξία', 'Αιγόκερω': 'φιλοδοξία, καριέρα και πειθαρχία', 'Υδροχόο': 'καινοτομία, φίλους και ελευθερία', 'Ιχθείς': 'διαίσθηση, όνειρα και πνευματικότητα' };
